import{_ as e,o as t,c as a,a5 as s}from"./chunks/framework.BmD0ICqc.js";const d=JSON.parse('{"title":"PC・OS・ハードウェアの用語集","description":"","frontmatter":{"title":"PC・OS・ハードウェアの用語集","study":{"source":"統合ガイド","status":"published","generated":true,"catalog":true,"section":"reference","format":"glossary","domain":"terms","summary":"PC・OS・ハードウェアで使う語の定義、用例、関連する解説記事。"}},"headers":[],"relativePath":"glossary/pc.md","filePath":"glossary/pc.md"}'),o={name:"glossary/pc.md"};function n(l,r,p,h,g,i){return t(),a("div",null,[...r[0]||(r[0]=[s('<h1 id="pc・os・ハードウェアの用語集" tabindex="-1">PC・OS・ハードウェアの用語集 <a class="header-anchor" href="#pc・os・ハードウェアの用語集" aria-label="Permalink to &quot;PC・OS・ハードウェアの用語集&quot;">​</a></h1><p><a href="/study/glossary/">用語集の入口・全用語検索</a></p><p>読み順で 55 項目を掲載しています。</p><h2 id="irq" tabindex="-1">IRQ <a class="header-anchor" href="#irq" aria-label="Permalink to &quot;IRQ {#irq}&quot;">​</a></h2><p><strong>IRQ / Interrupt Request</strong> ／ 読み あいあーるきゅー / わりこみようきゅう</p><p>機器などがCPU側に処理を求める割り込み要求。「IRQ番号」は、OSや機器の割り込みを識別する番号を指す。</p><p><strong>例</strong>　LinuxでIRQごとの割り込み回数を確認する。</p><p><strong>関連</strong>　<a href="/study/hardware/io/nic-receive-queues.html">NICの受信キュー</a> · <a href="/study/glossary/pc.html#interrupt">割り込み</a> · <a href="/study/glossary/pc.html#driver">ドライバー</a></p><p><strong>出典</strong>　<a href="https://docs.kernel.org/core-api/genericirq.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — 割り込みの処理</a> · <a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html" target="_blank" rel="noreferrer">Intel — Intel 64・IA-32 Software Developer Manuals</a></p><h2 id="iommu" tabindex="-1">IOMMU <a class="header-anchor" href="#iommu" aria-label="Permalink to &quot;IOMMU {#iommu}&quot;">​</a></h2><p><strong>IOMMU / Input–Output Memory Management Unit</strong> ／ 読み あいおーえむえむゆー</p><p>機器がDMAで指定するアドレスを変換し、その機器がアクセスできるメモリの範囲を制御する仕組み。</p><p><strong>例</strong>　IOMMUで機器に見せるDMA先を設定する。</p><p><strong>関連</strong>　<a href="/study/hardware/io/dma-and-iommu.html">DMAとIOMMU</a> · <a href="/study/glossary/pc.html#dma">DMA</a> · <a href="/study/glossary/pc.html#virtual-memory">仮想メモリ</a></p><p><strong>出典</strong>　<a href="https://docs.kernel.org/core-api/dma-api-howto.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — DMAマッピング</a></p><h2 id="ethernet-frame" tabindex="-1">Ethernetフレーム <a class="header-anchor" href="#ethernet-frame" aria-label="Permalink to &quot;Ethernetフレーム {#ethernet-frame}&quot;">​</a></h2><p><strong>Ethernet frame</strong> ／ 読み いーさねっとふれーむ</p><p>Ethernetのリンクでやり取りするデータの単位。送信元と宛先のMACアドレスなどの情報と、運ぶデータを含む。</p><p><strong>この分野での意味</strong>　例えばIPv4のパケットは、Ethernetフレームのデータ部分に入れて同じリンク上の機器へ送る。</p><p><strong>例</strong>　ルーターへ送るEthernetフレームに、次の機器のMACアドレスを入れる。</p><p><strong>関連</strong>　<a href="/study/network/ip-routing-and-ethernet.html">IPの経路選択とEthernet</a> · <a href="/study/glossary/pc.html#interrupt">割り込み</a> · <a href="/study/glossary/pc.html#throughput">スループット</a></p><p><strong>出典</strong>　<a href="https://datatracker.ietf.org/doc/rfc894/" target="_blank" rel="noreferrer">IETF RFC 894 — EthernetフレームでのIPデータグラムの伝送</a></p><h2 id="watchdog" tabindex="-1">ウォッチドッグ <a class="header-anchor" href="#watchdog" aria-label="Permalink to &quot;ウォッチドッグ {#watchdog}&quot;">​</a></h2><p><strong>watchdog / watchdog timer</strong> ／ 読み うぉっちどっぐ</p><p>一定時間ごとに進行を示す通知を待ち、途絶えたときに再起動や診断などを行う監視機構。</p><p><strong>例</strong>　OSが通知を返せなくなり、ウォッチドッグが機器を再起動した。</p><p><strong>関連</strong>　<a href="/study/glossary/pc.html#hang">ハング</a> · <a href="/study/glossary/pc.html#freeze">フリーズ</a></p><p><strong>出典</strong>　<a href="https://docs.kernel.org/watchdog/watchdog-api.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — ウォッチドッグAPI</a> · <a href="https://uefi.org/specs/UEFI/2.11/03_Boot_Manager.html" target="_blank" rel="noreferrer">UEFI Forum — UEFI 2.11、Boot Manager</a></p><h2 id="kernel" tabindex="-1">カーネル <a class="header-anchor" href="#kernel" aria-label="Permalink to &quot;カーネル {#kernel}&quot;">​</a></h2><p><strong>kernel / operating system kernel</strong> ／ 読み かーねる</p><p>OSの中核。CPUで実行する仕事の割り当て、メモリ、機器へのアクセスなどを管理する。</p><p><strong>この分野での意味</strong>　GPU計算では、デバイス上で多くの処理単位に実行させる関数をカーネルと呼ぶこともある。</p><p><strong>例</strong>　カーネルがファイルを読む要求を処理する。</p><p><strong>関連</strong>　<a href="/study/os/operating-system-basics.html">OSの役割とユーザーモード・カーネル</a> · <a href="/study/glossary/pc.html#system-call">システムコール</a> · <a href="/study/glossary/pc.html#kernel-mode">カーネルモード</a> · <a href="/study/glossary/pc.html#driver">ドライバー</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/gettingstarted/user-mode-and-kernel-mode" target="_blank" rel="noreferrer">Microsoft — ユーザーモードとカーネルモード</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/procthread/about-processes-and-threads" target="_blank" rel="noreferrer">Microsoft — プロセスとスレッド</a> · <a href="https://docs.kernel.org/admin-guide/mm/concepts.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — メモリ管理の概念</a></p><h2 id="kernel-mode" tabindex="-1">カーネルモード <a class="header-anchor" href="#kernel-mode" aria-label="Permalink to &quot;カーネルモード {#kernel-mode}&quot;">​</a></h2><p><strong>kernel mode</strong> ／ 読み かーねるもーど</p><p>OSの中核や一部のドライバーが、CPUの特権操作や保護されたメモリにアクセスできる実行状態。</p><p><strong>例</strong>　システムコールでカーネルモードの処理へ移る。</p><p><strong>関連</strong>　<a href="/study/os/system-calls-and-privilege.html">システムコールと特権</a> · <a href="/study/glossary/pc.html#user-mode">ユーザーモード</a> · <a href="/study/glossary/pc.html#system-call">システムコール</a> · <a href="/study/glossary/pc.html#kernel">カーネル</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/gettingstarted/user-mode-and-kernel-mode" target="_blank" rel="noreferrer">Microsoft — ユーザーモードとカーネルモード</a> · <a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html" target="_blank" rel="noreferrer">Intel — Intel 64・IA-32 Software Developer Manuals</a></p><h2 id="virtual-memory" tabindex="-1">仮想メモリ <a class="header-anchor" href="#virtual-memory" aria-label="Permalink to &quot;仮想メモリ {#virtual-memory}&quot;">​</a></h2><p><strong>virtual memory</strong> ／ 読み かそうめもり</p><p>プログラムが使うアドレスを物理メモリなどの裏付けと分け、OSが配置とアクセス権を管理する仕組み。</p><p><strong>この分野での意味</strong>　RAM不足時のスワップは、仮想メモリの用途の一つ。</p><p><strong>例</strong>　別々のプロセスが同じ仮想アドレスを使う。</p><p><strong>関連</strong>　<a href="/study/os/virtual-memory.html">仮想メモリとアドレス変換</a> · <a href="/study/glossary/pc.html#paging">ページング</a> · <a href="/study/glossary/pc.html#page-table">ページテーブル</a> · <a href="/study/glossary/pc.html#swap">スワップ</a></p><p><strong>出典</strong>　<a href="https://docs.kernel.org/admin-guide/mm/concepts.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — メモリ管理の概念</a> · <a href="https://docs.kernel.org/mm/page_tables.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — ページテーブル</a></p><h2 id="environment-variable" tabindex="-1">環境変数 <a class="header-anchor" href="#environment-variable" aria-label="Permalink to &quot;環境変数 {#environment-variable}&quot;">​</a></h2><p><strong>environment variable</strong> ／ 読み かんきょうへんすう</p><p>プロセスに渡される名前と値の組。実行環境の設定やコマンド探索先を指定できる。</p><p><strong>この分野での意味</strong>　Windowsでは既定で子プロセスに親の環境が継承される。親が起動後に変更した値まで自動で伝わるわけではない。</p><p><strong>例</strong>　環境変数PATHに開発ツールのディレクトリを追加する。</p><p><strong>関連</strong>　<a href="/study/tools/terminal-shell-and-commands.html">ターミナル・シェル・コマンド</a> · <a href="/study/glossary/pc.html#process">プロセス</a> · <a href="/study/glossary/pc.html#path">パス</a> · <a href="/study/glossary/pc.html#registry">レジストリ</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/procthread/environment-variables" target="_blank" rel="noreferrer">Microsoft — 環境変数</a> · <a href="https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/path" target="_blank" rel="noreferrer">Microsoft — PATHの探索先</a></p><h2 id="cache" tabindex="-1">キャッシュ <a class="header-anchor" href="#cache" aria-label="Permalink to &quot;キャッシュ {#cache}&quot;">​</a></h2><p><strong>cache</strong> ／ 読み きゃっしゅ</p><p>使いそうなデータや結果を再利用しやすい場所に置いて、次の取得や計算を省く仕組み。</p><p><strong>この分野での意味</strong>　CPUキャッシュは主にメモリの内容、OSのファイルキャッシュはファイルの内容、アセットビルドのキャッシュは変換済み成果物を保持する。</p><p><strong>例</strong>　よく読むデータがCPUキャッシュに収まる。</p><p><strong>関連</strong>　<a href="/study/hardware/memory/ram-cache-and-storage.html">RAM・キャッシュ・ストレージの違い</a> · <a href="/study/os/windows-file-cache.html">Windowsのファイルキャッシュ</a> · <a href="/study/glossary/pc.html#cache-hit">キャッシュヒット</a> · <a href="/study/glossary/pc.html#cache-miss">キャッシュミス</a> · <a href="/study/glossary/pc.html#cache-line">キャッシュライン</a></p><p><strong>出典</strong>　<a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel64-and-ia32-architectures-optimization.html" target="_blank" rel="noreferrer">Intel — Intel 64・IA-32 Optimization Reference Manuals</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/fileio/file-caching" target="_blank" rel="noreferrer">Microsoft — ファイルキャッシュ</a></p><h2 id="cache-line" tabindex="-1">キャッシュライン <a class="header-anchor" href="#cache-line" aria-label="Permalink to &quot;キャッシュライン {#cache-line}&quot;">​</a></h2><p><strong>cache line / cache block</strong> ／ 読み きゃっしゅらいん</p><p>CPUキャッシュがメモリの内容を保持し、取得や更新を行う単位。1回のアクセスで近接する複数の値が同じラインに入ることがある。</p><p><strong>例</strong>　配列を順番に読み、取り込んだキャッシュライン内の値を使い切る。</p><p><strong>関連</strong>　<a href="/study/runtime/memory/cache-locality-aos-soa.html">キャッシュ局所性とAoS・SoA</a> · <a href="/study/glossary/pc.html#cache">キャッシュ</a> · <a href="/study/glossary/pc.html#cache-miss">キャッシュミス</a></p><p><strong>出典</strong>　<a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel64-and-ia32-architectures-optimization.html" target="_blank" rel="noreferrer">Intel — Intel 64・IA-32 Optimization Reference Manuals</a></p><h2 id="crash" tabindex="-1">クラッシュ <a class="header-anchor" href="#crash" aria-label="Permalink to &quot;クラッシュ {#crash}&quot;">​</a></h2><p><strong>crash</strong> ／ 読み くらっしゅ</p><p>エラーなどでアプリやOSが異常終了すること。</p><p><strong>この分野での意味</strong>　現場で「落ちる」と言うこともある。操作に応答しなくてもプロセスが残る場合は、ハングとして扱うことが多い。</p><p><strong>例</strong>　セーブ直後にクラッシュしたため、ダンプを調べる。</p><p><strong>関連</strong>　<a href="/study/glossary/pc.html#hang">ハング</a> · <a href="/study/glossary/pc.html#crash-dump">クラッシュダンプ</a> · <a href="/study/glossary/pc.html#blue-screen">ブルースクリーン</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/troubleshoot-application-service-crashing-behavior" target="_blank" rel="noreferrer">Microsoft — アプリケーションとサービスのクラッシュ</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/wer/collecting-user-mode-dumps" target="_blank" rel="noreferrer">Microsoft — ユーザーモードダンプ</a></p><h2 id="crash-dump" tabindex="-1">クラッシュダンプ <a class="header-anchor" href="#crash-dump" aria-label="Permalink to &quot;クラッシュダンプ {#crash-dump}&quot;">​</a></h2><p><strong>crash dump / memory dump</strong> ／ 読み くらっしゅだんぷ / めもりだんぷ</p><p>異常終了時などに、原因を調べるためメモリやスレッドの状態を保存したファイル。</p><p><strong>例</strong>　クラッシュダンプと対応するシンボルをデバッガーで開く。</p><p><strong>関連</strong>　<a href="/study/glossary/pc.html#crash">クラッシュ</a> · <a href="/study/glossary/pc.html#blue-screen">ブルースクリーン</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/wer/collecting-user-mode-dumps" target="_blank" rel="noreferrer">Microsoft — ユーザーモードダンプ</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-checks--blue-screens-" target="_blank" rel="noreferrer">Microsoft — Bug Checkと停止コード</a></p><h2 id="context-switch" tabindex="-1">コンテキストスイッチ <a class="header-anchor" href="#context-switch" aria-label="Permalink to &quot;コンテキストスイッチ {#context-switch}&quot;">​</a></h2><p><strong>context switch</strong> ／ 読み こんてきすとすいっち</p><p>CPUで実行するスレッドなどを切り替え、前の実行状態を保存して次の実行状態を復元すること。</p><p><strong>例</strong>　入力待ちに入ったスレッドから別のスレッドへ切り替える。</p><p><strong>関連</strong>　<a href="/study/os/thread-scheduling.html">スレッドのスケジューリング</a> · <a href="/study/glossary/pc.html#thread">スレッド</a> · <a href="/study/glossary/pc.html#scheduler">スケジューラー</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/procthread/context-switches" target="_blank" rel="noreferrer">Microsoft — コンテキストスイッチ</a></p><h2 id="service" tabindex="-1">サービス <a class="header-anchor" href="#service" aria-label="Permalink to &quot;サービス {#service}&quot;">​</a></h2><p><strong>service / Windows service</strong> ／ 読み さーびす</p><p>Windowsで、サービスコントロールマネージャーに登録して開始・停止などを管理するプログラム。</p><p><strong>この分野での意味</strong>　オンライン開発でいう「サービス」は、ネットワーク越しに機能を提供するシステムも指す。</p><p><strong>例</strong>　ログオン前にサーバー用のWindowsサービスを起動する。</p><p><strong>関連</strong>　<a href="/study/glossary/pc.html#daemon">デーモン</a> · <a href="/study/glossary/pc.html#process">プロセス</a> · <a href="/study/glossary/pc.html#registry">レジストリ</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/services/about-services" target="_blank" rel="noreferrer">Microsoft — Windowsサービス</a></p><h2 id="system-call" tabindex="-1">システムコール <a class="header-anchor" href="#system-call" aria-label="Permalink to &quot;システムコール {#system-call}&quot;">​</a></h2><p><strong>system call / syscall</strong> ／ 読み しすてむこーる / しすこーる</p><p>プログラムがOSカーネルに処理を要求するためのインターフェース。</p><p><strong>この分野での意味</strong>　公開APIの中にはユーザーモードだけで完了するものや、複数のシステムコールを発行するものもある。</p><p><strong>例</strong>　OSへ新しいファイルディスクリプターの取得を要求する。</p><p><strong>関連</strong>　<a href="/study/os/system-calls-and-privilege.html">システムコールと特権</a> · <a href="/study/glossary/pc.html#kernel">カーネル</a> · <a href="/study/glossary/pc.html#user-mode">ユーザーモード</a> · <a href="/study/glossary/pc.html#file-descriptor">ファイルディスクリプター</a></p><p><strong>出典</strong>　<a href="https://man7.org/linux/man-pages/man2/syscall.2.html" target="_blank" rel="noreferrer">Linux man-pages — syscall(2)</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/gettingstarted/user-mode-and-kernel-mode" target="_blank" rel="noreferrer">Microsoft — ユーザーモードとカーネルモード</a></p><h2 id="scheduler" tabindex="-1">スケジューラー <a class="header-anchor" href="#scheduler" aria-label="Permalink to &quot;スケジューラー {#scheduler}&quot;">​</a></h2><p><strong>scheduler / thread scheduler</strong> ／ 読み すけじゅーらー</p><p>実行できるスレッドのうち、どれをいつ、どの論理プロセッサで実行するか決める仕組み。</p><p><strong>この分野での意味</strong>　エンジン内のジョブスケジューラーは、仕事をワーカースレッドに割り振る。</p><p><strong>例</strong>　スケジューラーが実行可能になったスレッドにCPUを割り当てる。</p><p><strong>関連</strong>　<a href="/study/os/thread-scheduling.html">スレッドのスケジューリング</a> · <a href="/study/glossary/pc.html#thread">スレッド</a> · <a href="/study/glossary/pc.html#context-switch">コンテキストスイッチ</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/procthread/about-processes-and-threads" target="_blank" rel="noreferrer">Microsoft — プロセスとスレッド</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/procthread/context-switches" target="_blank" rel="noreferrer">Microsoft — コンテキストスイッチ</a></p><h2 id="throughput" tabindex="-1">スループット <a class="header-anchor" href="#throughput" aria-label="Permalink to &quot;スループット {#throughput}&quot;">​</a></h2><p><strong>throughput</strong> ／ 読み するーぷっと</p><p>単位時間あたりに処理や転送を完了できる量。測定では仕事の種類と条件をそろえる。</p><p><strong>この分野での意味</strong>　一つの要求にかかる時間を表すレイテンシと区別する。複数の仕事を並行に進めると、待ち時間が同じでも完了する件数を増やせる。</p><p><strong>例</strong>　データを展開する処理のスループットをMB/sで比べる。</p><p><strong>関連</strong>　<a href="/study/hardware/memory/dram-channels-and-bandwidth.html">DRAMチャネルと帯域</a> · <a href="/study/glossary/pc.html#latency">レイテンシ</a> · <a href="/study/glossary/pc.html#bandwidth">帯域</a></p><p><strong>出典</strong>　<a href="https://www.rfc-editor.org/info/rfc1242/" target="_blank" rel="noreferrer">IETF RFC 1242 — ネットワーク機器の計測用語</a> · <a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel64-and-ia32-architectures-optimization.html" target="_blank" rel="noreferrer">Intel — Intel 64・IA-32 Optimization Reference Manuals</a></p><h2 id="thread" tabindex="-1">スレッド <a class="header-anchor" href="#thread" aria-label="Permalink to &quot;スレッド {#thread}&quot;">​</a></h2><p><strong>thread</strong> ／ 読み すれっど</p><p>OSがCPUに割り当てる実行の流れ。同じプロセスのスレッドは通常アドレス空間を共有し、スタックや実行位置をそれぞれ持つ。</p><p><strong>例</strong>　描画とデータの展開を別スレッドに分ける。</p><p><strong>関連</strong>　<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a> · <a href="/study/glossary/pc.html#process">プロセス</a> · <a href="/study/glossary/pc.html#context-switch">コンテキストスイッチ</a> · <a href="/study/glossary/pc.html#scheduler">スケジューラー</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/procthread/about-processes-and-threads" target="_blank" rel="noreferrer">Microsoft — プロセスとスレッド</a></p><h2 id="swap" tabindex="-1">スワップ <a class="header-anchor" href="#swap" aria-label="Permalink to &quot;スワップ {#swap}&quot;">​</a></h2><p><strong>swap / swap space / paging file</strong> ／ 読み すわっぷ</p><p>RAMに置いていたページの内容を退避し、必要になったときに戻す仕組み。退避に使う領域も指す。</p><p><strong>この分野での意味</strong>　OSによって仕組みや呼び方が異なる。Windowsにはページファイルがあり、描画でいうswap chainの画像切り替えとは用途が違う。</p><p><strong>例</strong>　RAMの使用量が増えてスワップ領域への書き出しが起きる。</p><p><strong>関連</strong>　<a href="/study/os/virtual-memory.html">仮想メモリとアドレス変換</a> · <a href="/study/glossary/pc.html#virtual-memory">仮想メモリ</a> · <a href="/study/glossary/pc.html#working-set">ワーキングセット</a> · <a href="/study/glossary/pc.html#page-fault">ページフォルト</a></p><p><strong>出典</strong>　<a href="https://docs.kernel.org/admin-guide/mm/concepts.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — メモリ管理の概念</a> · <a href="https://learn.microsoft.com/en-us/troubleshoot/windows-client/performance/how-to-determine-the-appropriate-page-file-size-for-64-bit-versions-of-windows" target="_blank" rel="noreferrer">Microsoft — 64ビットWindowsのページファイル</a></p><h2 id="bandwidth" tabindex="-1">帯域 <a class="header-anchor" href="#bandwidth" aria-label="Permalink to &quot;帯域 {#bandwidth}&quot;">​</a></h2><p><strong>bandwidth / data transfer bandwidth</strong> ／ 読み たいいき</p><p>メモリや通信路が単位時間に転送できるデータ量。理論上の上限を指す場合と実測値を指す場合がある。</p><p><strong>この分野での意味</strong>　信号処理の帯域は、扱う周波数範囲の幅をHzで表すことがある。</p><p><strong>例</strong>　メモリ帯域をGB/sで見積もる。</p><p><strong>関連</strong>　<a href="/study/hardware/memory/dram-channels-and-bandwidth.html">DRAMチャネルと帯域</a> · <a href="/study/glossary/pc.html#throughput">スループット</a> · <a href="/study/glossary/pc.html#latency">レイテンシ</a> · <a href="/study/glossary/pc.html#pcie">PCI Express</a></p><p><strong>出典</strong>　<a href="https://pcisig.com/faq?field_category_value%5B%5D=pci_express_7.0" target="_blank" rel="noreferrer">PCI-SIG — PCI Expressの仕様と帯域</a> · <a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel64-and-ia32-architectures-optimization.html" target="_blank" rel="noreferrer">Intel — Intel 64・IA-32 Optimization Reference Manuals</a> · <a href="https://www.itu.int/dms_pubrec/itu-r/rec/sm/R-REC-SM.328-12-202509-I%21%21PDF-E.pdf" target="_blank" rel="noreferrer">ITU-R SM.328-12 — 電波のスペクトルと帯域幅</a></p><h2 id="dma" tabindex="-1">DMA <a class="header-anchor" href="#dma" aria-label="Permalink to &quot;DMA {#dma}&quot;">​</a></h2><p><strong>DMA / Direct Memory Access</strong> ／ 読み でぃーえむえー</p><p>CPUが各データを一つずつ移さず、機器や転送用コントローラーがメモリとのデータ転送を行う仕組み。</p><p><strong>例</strong>　NICが受信データをDMAでRAMへ書く。</p><p><strong>関連</strong>　<a href="/study/hardware/io/dma-and-iommu.html">DMAとIOMMU</a> · <a href="/study/glossary/pc.html#iommu">IOMMU</a> · <a href="/study/glossary/pc.html#interrupt">割り込み</a> · <a href="/study/glossary/pc.html#pcie">PCI Express</a></p><p><strong>出典</strong>　<a href="https://docs.kernel.org/core-api/dma-api-howto.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — DMAマッピング</a></p><h2 id="tlb" tabindex="-1">TLB <a class="header-anchor" href="#tlb" aria-label="Permalink to &quot;TLB {#tlb}&quot;">​</a></h2><p><strong>TLB / Translation Lookaside Buffer</strong> ／ 読み てぃーえるびー</p><p>仮想アドレスから物理アドレスへの変換結果を保持するCPU内のキャッシュ。</p><p><strong>この分野での意味</strong>　TLBミスでも、有効な対応をページテーブルで見つけられれば、通常ページフォルトを起こさずに処理を続けられる。</p><p><strong>例</strong>　広い範囲のページを飛び飛びに読むとTLBミスが増えることがある。</p><p><strong>関連</strong>　<a href="/study/os/virtual-memory.html">仮想メモリとアドレス変換</a> · <a href="/study/glossary/pc.html#page-table">ページテーブル</a> · <a href="/study/glossary/pc.html#cache-miss">キャッシュミス</a> · <a href="/study/glossary/pc.html#page-fault">ページフォルト</a></p><p><strong>出典</strong>　<a href="https://docs.kernel.org/mm/page_tables.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — ページテーブル</a> · <a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html" target="_blank" rel="noreferrer">Intel — Intel 64・IA-32 Software Developer Manuals</a></p><h2 id="daemon" tabindex="-1">デーモン <a class="header-anchor" href="#daemon" aria-label="Permalink to &quot;デーモン {#daemon}&quot;">​</a></h2><p><strong>daemon</strong> ／ 読み でーもん</p><p>Unix系OSでバックグラウンドに常駐し、要求の受け付けや定期的な処理などを行うプロセス。</p><p><strong>例</strong>　ログを集めるデーモンがシステム起動時に立ち上がる。</p><p><strong>関連</strong>　<a href="/study/glossary/pc.html#service">サービス</a> · <a href="/study/glossary/pc.html#process">プロセス</a></p><p><strong>出典</strong>　<a href="https://www.freedesktop.org/software/systemd/man/latest/daemon.html" target="_blank" rel="noreferrer">systemd — daemon(7)</a></p><h2 id="driver" tabindex="-1">ドライバー <a class="header-anchor" href="#driver" aria-label="Permalink to &quot;ドライバー {#driver}&quot;">​</a></h2><p><strong>driver / device driver</strong> ／ 読み どらいばー</p><p>OSの入出力要求を機器や下位層の操作へつなぐソフトウェア。OS上の仮想的な機能を提供するものもある。</p><p><strong>この分野での意味</strong>　Windowsのドライバーには、ユーザーモードで動作するものもある。</p><p><strong>例</strong>　GPUドライバーが描画コマンドの実行を支える。</p><p><strong>関連</strong>　<a href="/study/os/operating-system-basics.html">OSの役割とユーザーモード・カーネル</a> · <a href="/study/glossary/pc.html#kernel">カーネル</a> · <a href="/study/glossary/pc.html#firmware">ファームウェア</a> · <a href="/study/glossary/pc.html#interrupt">割り込み</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/gettingstarted/what-is-a-driver-" target="_blank" rel="noreferrer">Microsoft — ドライバーの役割</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/gettingstarted/user-mode-and-kernel-mode" target="_blank" rel="noreferrer">Microsoft — ユーザーモードとカーネルモード</a></p><h2 id="bios" tabindex="-1">BIOS <a class="header-anchor" href="#bios" aria-label="Permalink to &quot;BIOS {#bios}&quot;">​</a></h2><p><strong>BIOS / Basic Input/Output System</strong> ／ 読み ばいおす</p><p>PCの起動時に機器を初期化し、起動用コードへ制御を渡す従来型のファームウェア。</p><p><strong>この分野での意味</strong>　日常的にはUEFI機の設定画面も「BIOS」と呼ばれる。起動方式を指定するときはレガシーBIOSとUEFIを区別する。</p><p><strong>例</strong>　古いPCをレガシーBIOS方式で起動する。</p><p><strong>関連</strong>　<a href="/study/glossary/pc.html#uefi">UEFI</a> · <a href="/study/glossary/pc.html#firmware">ファームウェア</a> · <a href="/study/glossary/pc.html#post">電源投入時自己診断</a></p><p><strong>出典</strong>　<a href="https://csrc.nist.gov/glossary/term/Basic_Input_Output_System" target="_blank" rel="noreferrer">NIST — Basic Input/Output System</a> · <a href="https://learn.microsoft.com/en-us/windows/client-management/advanced-troubleshooting-boot-problems" target="_blank" rel="noreferrer">Microsoft — Windowsの起動段階</a> · <a href="https://uefi.org/specs/UEFI/2.11/03_Boot_Manager.html" target="_blank" rel="noreferrer">UEFI Forum — UEFI 2.11、Boot Manager</a></p><h2 id="path" tabindex="-1">パス <a class="header-anchor" href="#path" aria-label="Permalink to &quot;パス {#path}&quot;">​</a></h2><p><strong>path / pathname</strong> ／ 読み ぱす</p><p>ファイルやディレクトリなどの場所を、名前の並びで指定する文字列。</p><p><strong>この分野での意味</strong>　環境変数のPATHはコマンドを探すディレクトリの一覧。描画で英語がpassの場合は処理の一段階を指す。</p><p><strong>例</strong>　設定ファイルの相対パスを作業ディレクトリから解決する。</p><p><strong>関連</strong>　<a href="/study/os/files-and-paths.html">ファイルとパス</a> · <a href="/study/glossary/pc.html#file-system">ファイルシステム</a> · <a href="/study/glossary/pc.html#environment-variable">環境変数</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/naming-a-file" target="_blank" rel="noreferrer">Microsoft — ファイル名、パス、名前空間</a> · <a href="https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/path" target="_blank" rel="noreferrer">Microsoft — PATHの探索先</a></p><h2 id="hang" tabindex="-1">ハング <a class="header-anchor" href="#hang" aria-label="Permalink to &quot;ハング {#hang}&quot;">​</a></h2><p><strong>hang / unresponsive</strong> ／ 読み はんぐ / はんぐあっぷ</p><p>プロセスやシステムが終了せず、期待した処理の進行や応答が観測できない状態。</p><p><strong>この分野での意味</strong>　フリーズと重なる呼び方。ハングという語だけでは、待機、処理の過負荷、無限ループなどの原因は分からない。</p><p><strong>例</strong>　終了ボタンを押しても応答せず、アプリがハングした。</p><p><strong>関連</strong>　<a href="/study/runtime/memory/concurrency-bugs.html">並行処理のバグ</a> · <a href="/study/glossary/pc.html#freeze">フリーズ</a> · <a href="/study/glossary/pc.html#crash">クラッシュ</a> · <a href="/study/glossary/pc.html#watchdog">ウォッチドッグ</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/troubleshoot/windows-client/performance/windows-based-computer-freeze-troubleshooting" target="_blank" rel="noreferrer">Microsoft — Windowsのフリーズ</a></p><h2 id="handle" tabindex="-1">ハンドル <a class="header-anchor" href="#handle" aria-label="Permalink to &quot;ハンドル {#handle}&quot;">​</a></h2><p><strong>handle / object handle</strong> ／ 読み はんどる</p><p>APIでリソースを指定するための値。Windowsではファイルやイベントなど、開いたOSオブジェクトを操作するために使う。</p><p><strong>この分野での意味</strong>　ゲームではスロット番号と世代などでオブジェクトを識別し、DCCツールでは画面上で対象を操作するつまみも指す。</p><p><strong>例</strong>　読み取りを終えたファイルのハンドルを閉じる。</p><p><strong>関連</strong>　<a href="/study/os/windows-handles.html">Windowsのハンドル</a> · <a href="/study/algorithms/generational-handles.html">世代付きハンドル</a> · <a href="/study/glossary/pc.html#file-descriptor">ファイルディスクリプター</a> · <a href="/study/glossary/pc.html#process">プロセス</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/kernel/object-handles" target="_blank" rel="noreferrer">Microsoft — オブジェクトハンドル</a> · <a href="https://www.sidefx.com/docs/houdini/basics/handles.html" target="_blank" rel="noreferrer">SideFX — Houdiniの操作ハンドル</a></p><h2 id="pcie" tabindex="-1">PCI Express <a class="header-anchor" href="#pcie" aria-label="Permalink to &quot;PCI Express {#pcie}&quot;">​</a></h2><p><strong>PCIe / PCI Express</strong> ／ 読み ぴーしーあいえくすぷれす / ぴーしーあいいー</p><p>PCのCPUやチップセットと、GPUやSSDなどの機器を接続する高速な入出力規格。</p><p><strong>例</strong>　GPUがPCIeの何レーンで接続されているか調べる。</p><p><strong>関連</strong>　<a href="/study/hardware/io/pcie-links.html">PCI Expressのリンクと帯域</a> · <a href="/study/glossary/pc.html#dma">DMA</a> · <a href="/study/glossary/pc.html#bandwidth">帯域</a></p><p><strong>出典</strong>　<a href="https://pcisig.com/faq?field_category_value%5B%5D=pci_express_7.0" target="_blank" rel="noreferrer">PCI-SIG — PCI Expressの仕様と帯域</a></p><h2 id="cache-hit" tabindex="-1">キャッシュヒット <a class="header-anchor" href="#cache-hit" aria-label="Permalink to &quot;キャッシュヒット {#cache-hit}&quot;">​</a></h2><p><strong>hit / cache hit</strong> ／ 読み ひっと / きゃっしゅひっと</p><p>必要なデータや結果が、調べたキャッシュに見つかること。</p><p><strong>この分野での意味</strong>　ゲームの当たり判定でいう「ヒット」は、攻撃などが対象に当たること。</p><p><strong>例</strong>　L1キャッシュにヒットし、下位のキャッシュを参照せずに済んだ。</p><p><strong>関連</strong>　<a href="/study/runtime/memory/cache-locality-aos-soa.html">キャッシュ局所性とAoS・SoA</a> · <a href="/study/glossary/pc.html#cache">キャッシュ</a> · <a href="/study/glossary/pc.html#cache-miss">キャッシュミス</a></p><p><strong>出典</strong>　<a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel64-and-ia32-architectures-optimization.html" target="_blank" rel="noreferrer">Intel — Intel 64・IA-32 Optimization Reference Manuals</a></p><h2 id="firmware" tabindex="-1">ファームウェア <a class="header-anchor" href="#firmware" aria-label="Permalink to &quot;ファームウェア {#firmware}&quot;">​</a></h2><p><strong>firmware</strong> ／ 読み ふぁーむうぇあ</p><p>機器に組み込まれ、機器の初期化や動作を担うソフトウェア。更新できる製品もある。</p><p><strong>この分野での意味</strong>　PC側でOSの要求を仲介するソフトウェアは、通常ドライバーと呼ぶ。</p><p><strong>例</strong>　SSDのファームウェアを更新する。</p><p><strong>関連</strong>　<a href="/study/hardware/computer-components.html">コンピュータを構成する部品</a> · <a href="/study/glossary/pc.html#driver">ドライバー</a> · <a href="/study/glossary/pc.html#uefi">UEFI</a></p><p><strong>出典</strong>　<a href="https://csrc.nist.gov/glossary/term/firmware" target="_blank" rel="noreferrer">NIST — firmware</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/gettingstarted/what-is-a-driver-" target="_blank" rel="noreferrer">Microsoft — ドライバーの役割</a></p><h2 id="file-system" tabindex="-1">ファイルシステム <a class="header-anchor" href="#file-system" aria-label="Permalink to &quot;ファイルシステム {#file-system}&quot;">​</a></h2><p><strong>file system / filesystem</strong> ／ 読み ふぁいるしすてむ</p><p>ファイルの内容やメタデータを管理し、パスからデータにアクセスできるようにする仕組み。</p><p><strong>例</strong>　ファイルシステムがファイル名から対応するデータを探す。</p><p><strong>関連</strong>　<a href="/study/os/files-and-paths.html">ファイルとパス</a> · <a href="/study/glossary/pc.html#mount">マウント</a> · <a href="/study/glossary/pc.html#path">パス</a> · <a href="/study/glossary/pc.html#file-descriptor">ファイルディスクリプター</a></p><p><strong>出典</strong>　<a href="https://docs.kernel.org/filesystems/vfs.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — 仮想ファイルシステム</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/fileio/naming-a-file" target="_blank" rel="noreferrer">Microsoft — ファイル名、パス、名前空間</a></p><h2 id="file-descriptor" tabindex="-1">ファイルディスクリプター <a class="header-anchor" href="#file-descriptor" aria-label="Permalink to &quot;ファイルディスクリプター {#file-descriptor}&quot;">​</a></h2><p><strong>file descriptor / fd</strong> ／ 読み ふぁいるでぃすくりぷたー</p><p>Unix系OSで、開いたファイルやパイプ、ソケットなどをプロセス内で指定するための非負の整数。</p><p><strong>例</strong>　ファイルディスクリプターをreadに渡す。</p><p><strong>関連</strong>　<a href="/study/os/pipes-and-process-io.html">パイプとプロセスの入出力</a> · <a href="/study/glossary/pc.html#handle">ハンドル</a> · <a href="/study/glossary/pc.html#file-system">ファイルシステム</a></p><p><strong>出典</strong>　<a href="https://man7.org/linux/man-pages/man2/open.2.html" target="_blank" rel="noreferrer">Linux man-pages — open(2)</a></p><h2 id="boot" tabindex="-1">ブート <a class="header-anchor" href="#boot" aria-label="Permalink to &quot;ブート {#boot}&quot;">​</a></h2><p><strong>boot / booting</strong> ／ 読み ぶーと / きどう</p><p>PCを起動し、ファームウェアやローダーを経てOSを動かせる状態にすること。</p><p><strong>この分野での意味</strong>　ゲームではタイトルの起動時に行う初期化の一連の処理を指すこともある。</p><p><strong>例</strong>　USBメモリからOSをブートする。</p><p><strong>関連</strong>　<a href="/study/glossary/pc.html#bootstrap">ブートストラップ</a> · <a href="/study/glossary/pc.html#boot-loader">ブートローダー</a> · <a href="/study/glossary/pc.html#uefi">UEFI</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/client-management/advanced-troubleshooting-boot-problems" target="_blank" rel="noreferrer">Microsoft — Windowsの起動段階</a> · <a href="https://uefi.org/specs/UEFI/2.11/03_Boot_Manager.html" target="_blank" rel="noreferrer">UEFI Forum — UEFI 2.11、Boot Manager</a></p><h2 id="bootstrap" tabindex="-1">ブートストラップ <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;ブートストラップ {#bootstrap}&quot;">​</a></h2><p><strong>bootstrap / bootstrap code</strong> ／ 読み ぶーとすとらっぷ</p><p>起動に必要な最初の小さな処理で、後続のローダーや実行環境を立ち上げること。そのためのコードも指す。</p><p><strong>この分野での意味</strong>　コンパイラ開発では、既存の処理系を使って新しい処理系を構築する過程にも使う。</p><p><strong>例</strong>　レガシーBIOSの起動経路で、最初のブートストラップコードが次段を読み込む。</p><p><strong>関連</strong>　<a href="/study/glossary/pc.html#boot">ブート</a> · <a href="/study/glossary/pc.html#boot-loader">ブートローダー</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/client-management/advanced-troubleshooting-boot-problems" target="_blank" rel="noreferrer">Microsoft — Windowsの起動段階</a> · <a href="https://gcc.gnu.org/install/build.html" target="_blank" rel="noreferrer">GNU Project — GCCのブートストラップ</a></p><h2 id="boot-loader" tabindex="-1">ブートローダー <a class="header-anchor" href="#boot-loader" aria-label="Permalink to &quot;ブートローダー {#boot-loader}&quot;">​</a></h2><p><strong>boot loader / OS loader</strong> ／ 読み ぶーとろーだー</p><p>起動時にOSのカーネルなどを読み込み、実行に必要な状態を整えて制御を渡すプログラム。</p><p><strong>この分野での意味</strong>　どのOSやローダーを起動するか決める部分はブートマネージャーと呼ぶことがある。</p><p><strong>例</strong>　ブートローダーがカーネルと初期ドライバーを読み込む。</p><p><strong>関連</strong>　<a href="/study/glossary/pc.html#boot">ブート</a> · <a href="/study/glossary/pc.html#bootstrap">ブートストラップ</a> · <a href="/study/glossary/pc.html#kernel">カーネル</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/client-management/advanced-troubleshooting-boot-problems" target="_blank" rel="noreferrer">Microsoft — Windowsの起動段階</a> · <a href="https://uefi.org/specs/UEFI/2.11/03_Boot_Manager.html" target="_blank" rel="noreferrer">UEFI Forum — UEFI 2.11、Boot Manager</a></p><h2 id="freeze" tabindex="-1">フリーズ <a class="header-anchor" href="#freeze" aria-label="Permalink to &quot;フリーズ {#freeze}&quot;">​</a></h2><p><strong>freeze / unresponsive</strong> ／ 読み ふりーず</p><p>操作に応答せず、画面や処理が止まったように見える状態。アプリだけの場合とOS全体の場合がある。</p><p><strong>例</strong>　ロード画面で入力を受け付けずフリーズする。</p><p><strong>関連</strong>　<a href="/study/os/thread-scheduling.html">スレッドのスケジューリング</a> · <a href="/study/glossary/pc.html#hang">ハング</a> · <a href="/study/glossary/pc.html#crash">クラッシュ</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/troubleshoot/windows-client/performance/windows-based-computer-freeze-troubleshooting" target="_blank" rel="noreferrer">Microsoft — Windowsのフリーズ</a></p><h2 id="blue-screen" tabindex="-1">ブルースクリーン <a class="header-anchor" href="#blue-screen" aria-label="Permalink to &quot;ブルースクリーン {#blue-screen}&quot;">​</a></h2><p><strong>BSOD / Blue Screen of Death / bug check</strong> ／ 読み ぶるーすくりーん / びーえすおーでぃー</p><p>Windowsが処理の続行が危険と判断して停止したときの通称。停止コードやダンプが原因調査の手がかりになる。</p><p><strong>この分野での意味</strong>　エラー画面の色や表示はWindowsの版などで変わる。Windowsの技術文書ではbug checkやstop codeと呼ぶ。</p><p><strong>例</strong>　ブルースクリーンで表示された停止コードを控える。</p><p><strong>関連</strong>　<a href="/study/glossary/pc.html#crash">クラッシュ</a> · <a href="/study/glossary/pc.html#crash-dump">クラッシュダンプ</a> · <a href="/study/glossary/pc.html#kernel">カーネル</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-checks--blue-screens-" target="_blank" rel="noreferrer">Microsoft — Bug Checkと停止コード</a> · <a href="https://support.microsoft.com/en-us/windows/experience/performance-optimization/troubleshooting-windows-unexpected-restarts-and-stop-code-errors" target="_blank" rel="noreferrer">Microsoft — Windowsの予期しない再起動と停止コード</a></p><h2 id="process" tabindex="-1">プロセス <a class="header-anchor" href="#process" aria-label="Permalink to &quot;プロセス {#process}&quot;">​</a></h2><p><strong>process</strong> ／ 読み ぷろせす</p><p>実行中のプログラムに、仮想アドレス空間、権限、開いているリソースなどをまとめた単位。</p><p><strong>この分野での意味</strong>　同じ実行ファイルを2回起動すると、別々のプロセスが作られる構成にできる。</p><p><strong>例</strong>　ゲームとエディターを別プロセスで動かす。</p><p><strong>関連</strong>　<a href="/study/os/process-startup.html">プロセスが起動するまで</a> · <a href="/study/glossary/pc.html#thread">スレッド</a> · <a href="/study/glossary/pc.html#handle">ハンドル</a> · <a href="/study/glossary/pc.html#virtual-memory">仮想メモリ</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/procthread/about-processes-and-threads" target="_blank" rel="noreferrer">Microsoft — プロセスとスレッド</a></p><h2 id="page" tabindex="-1">ページ <a class="header-anchor" href="#page" aria-label="Permalink to &quot;ページ {#page}&quot;">​</a></h2><p><strong>memory page / page</strong> ／ 読み ぺーじ</p><p>OSやCPUがアドレスの変換、保護、メモリ管理に使う固定長の範囲。大きさは構成や用途によって異なる。</p><p><strong>例</strong>　アクセス権をページ単位で設定する。</p><p><strong>関連</strong>　<a href="/study/os/virtual-memory.html">仮想メモリとアドレス変換</a> · <a href="/study/glossary/pc.html#paging">ページング</a> · <a href="/study/glossary/pc.html#page-table">ページテーブル</a> · <a href="/study/glossary/pc.html#page-fault">ページフォルト</a></p><p><strong>出典</strong>　<a href="https://docs.kernel.org/mm/page_tables.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — ページテーブル</a></p><h2 id="page-table" tabindex="-1">ページテーブル <a class="header-anchor" href="#page-table" aria-label="Permalink to &quot;ページテーブル {#page-table}&quot;">​</a></h2><p><strong>page table</strong> ／ 読み ぺーじてーぶる</p><p>仮想ページと物理メモリの対応や、そのページのアクセス権などを記録する表。</p><p><strong>例</strong>　ページテーブルを参照して仮想アドレスを変換する。</p><p><strong>関連</strong>　<a href="/study/os/virtual-memory.html">仮想メモリとアドレス変換</a> · <a href="/study/glossary/pc.html#page">ページ</a> · <a href="/study/glossary/pc.html#tlb">TLB</a> · <a href="/study/glossary/pc.html#virtual-memory">仮想メモリ</a></p><p><strong>出典</strong>　<a href="https://docs.kernel.org/mm/page_tables.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — ページテーブル</a> · <a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html" target="_blank" rel="noreferrer">Intel — Intel 64・IA-32 Software Developer Manuals</a></p><h2 id="page-fault" tabindex="-1">ページフォルト <a class="header-anchor" href="#page-fault" aria-label="Permalink to &quot;ページフォルト {#page-fault}&quot;">​</a></h2><p><strong>page fault</strong> ／ 読み ぺーじふぉると</p><p>ページが未配置だったりアクセスが許可されなかったりして、メモリアクセスを続けるためにOSの処理が必要になる例外。</p><p><strong>この分野での意味</strong>　必要なページを割り当てて処理を続けられる場合もあり、ストレージへの読み込みを伴うとは限らない。</p><p><strong>例</strong>　確保した領域の初回アクセスでページフォルトが起きる。</p><p><strong>関連</strong>　<a href="/study/os/virtual-memory.html">仮想メモリとアドレス変換</a> · <a href="/study/glossary/pc.html#paging">ページング</a> · <a href="/study/glossary/pc.html#page-table">ページテーブル</a> · <a href="/study/glossary/pc.html#working-set">ワーキングセット</a></p><p><strong>出典</strong>　<a href="https://docs.kernel.org/mm/page_tables.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — ページテーブル</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/memory/working-set" target="_blank" rel="noreferrer">Microsoft — ワーキングセット</a></p><h2 id="paging" tabindex="-1">ページング <a class="header-anchor" href="#paging" aria-label="Permalink to &quot;ページング {#paging}&quot;">​</a></h2><p><strong>paging</strong> ／ 読み ぺーじんぐ</p><p>メモリをページに分け、仮想アドレスの対応付けやRAMへの配置をページ単位で管理すること。</p><p><strong>この分野での意味</strong>　「ページングI/O」は、ページの読み込みや書き戻しに伴う入出力を指す。</p><p><strong>例</strong>　必要になったページをRAMに読み込む。</p><p><strong>関連</strong>　<a href="/study/os/virtual-memory.html">仮想メモリとアドレス変換</a> · <a href="/study/glossary/pc.html#virtual-memory">仮想メモリ</a> · <a href="/study/glossary/pc.html#page-table">ページテーブル</a> · <a href="/study/glossary/pc.html#page-fault">ページフォルト</a></p><p><strong>出典</strong>　<a href="https://docs.kernel.org/admin-guide/mm/concepts.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — メモリ管理の概念</a> · <a href="https://docs.kernel.org/mm/page_tables.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — ページテーブル</a></p><h2 id="polling" tabindex="-1">ポーリング <a class="header-anchor" href="#polling" aria-label="Permalink to &quot;ポーリング {#polling}&quot;">​</a></h2><p><strong>polling</strong> ／ 読み ぽーりんぐ</p><p>状態の変化を知るため、同じ対象を定期的または繰り返し調べること。</p><p><strong>例</strong>　受信キューにデータが届いたかポーリングする。</p><p><strong>関連</strong>　<a href="/study/hardware/io/nic-receive-queues.html">NICの受信キュー</a> · <a href="/study/glossary/pc.html#interrupt">割り込み</a> · <a href="/study/glossary/pc.html#latency">レイテンシ</a></p><p><strong>出典</strong>　<a href="https://docs.kernel.org/networking/napi.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — NAPI</a></p><h2 id="post" tabindex="-1">電源投入時自己診断 <a class="header-anchor" href="#post" aria-label="Permalink to &quot;電源投入時自己診断 {#post}&quot;">​</a></h2><p><strong>POST / Power-On Self-Test</strong> ／ 読み ぽすと / でんげんとうにゅうじじこしんだん</p><p>PCの電源投入後にファームウェアが行う基本的なハードウェアの診断。</p><p><strong>例</strong>　POSTでメモリの初期化に失敗する。</p><p><strong>関連</strong>　<a href="/study/glossary/pc.html#bios">BIOS</a> · <a href="/study/glossary/pc.html#uefi">UEFI</a> · <a href="/study/glossary/pc.html#boot">ブート</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/client-management/advanced-troubleshooting-boot-problems" target="_blank" rel="noreferrer">Microsoft — Windowsの起動段階</a></p><h2 id="hot-plug" tabindex="-1">ホットプラグ <a class="header-anchor" href="#hot-plug" aria-label="Permalink to &quot;ホットプラグ {#hot-plug}&quot;">​</a></h2><p><strong>hot plug / hot plugging</strong> ／ 読み ほっとぷらぐ</p><p>電源を切らずに、対応する機器を接続または取り外せること。</p><p><strong>この分野での意味</strong>　ストレージを動作中に外す場合は、未完了の書き込みや安全な取り外しの手順も確認する。</p><p><strong>例</strong>　実行中にUSBゲームパッドを接続して認識させる。</p><p><strong>関連</strong>　<a href="/study/hardware/io/usb-keyboard-raw-input.html">USBキーボードの入力とWindowsのRaw Input</a> · <a href="/study/glossary/pc.html#driver">ドライバー</a> · <a href="/study/glossary/pc.html#mount">マウント</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/kernel/introduction-to-plug-and-play" target="_blank" rel="noreferrer">Microsoft — WindowsのPlug and Play</a></p><h2 id="mount" tabindex="-1">マウント <a class="header-anchor" href="#mount" aria-label="Permalink to &quot;マウント {#mount}&quot;">​</a></h2><p><strong>mount / mount point</strong> ／ 読み まうんと</p><p>ファイルシステムをOSの名前空間に接続し、ある場所から中身にアクセスできるようにすること。</p><p><strong>この分野での意味</strong>　ゲームのパックを「マウントする」と言う場合は、エンジン内の仮想ファイルシステムにパックを登録することがある。</p><p><strong>例</strong>　USBドライブをディレクトリにマウントする。</p><p><strong>関連</strong>　<a href="/study/os/files-and-paths.html">ファイルとパス</a> · <a href="/study/glossary/pc.html#file-system">ファイルシステム</a> · <a href="/study/glossary/pc.html#path">パス</a></p><p><strong>出典</strong>　<a href="https://man7.org/linux/man-pages/man2/mount.2.html" target="_blank" rel="noreferrer">Linux man-pages — mount(2)</a> · <a href="https://docs.kernel.org/filesystems/vfs.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — 仮想ファイルシステム</a> · <a href="https://dev.epicgames.com/documentation/unreal-engine/API/Runtime/PakFile/FPakPlatformFile/Mount?application_version=5.8" target="_blank" rel="noreferrer">Epic Games — Unreal Engine 5.8 FPakPlatformFile::Mount</a></p><h2 id="cache-miss" tabindex="-1">キャッシュミス <a class="header-anchor" href="#cache-miss" aria-label="Permalink to &quot;キャッシュミス {#cache-miss}&quot;">​</a></h2><p><strong>miss / cache miss</strong> ／ 読み みす / きゃっしゅみす</p><p>必要なデータや結果が、調べたキャッシュにないこと。下の階層から取り寄せたり、計算し直したりする。</p><p><strong>例</strong>　L1でミスしたが、L2にはデータがあった。</p><p><strong>関連</strong>　<a href="/study/runtime/memory/cache-locality-aos-soa.html">キャッシュ局所性とAoS・SoA</a> · <a href="/study/glossary/pc.html#cache">キャッシュ</a> · <a href="/study/glossary/pc.html#cache-hit">キャッシュヒット</a> · <a href="/study/glossary/pc.html#latency">レイテンシ</a></p><p><strong>出典</strong>　<a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel64-and-ia32-architectures-optimization.html" target="_blank" rel="noreferrer">Intel — Intel 64・IA-32 Optimization Reference Manuals</a></p><h2 id="file-mapping" tabindex="-1">メモリマップドファイル <a class="header-anchor" href="#file-mapping" aria-label="Permalink to &quot;メモリマップドファイル {#file-mapping}&quot;">​</a></h2><p><strong>memory-mapped file / file mapping</strong> ／ 読み めもりまっぷどふぁいる</p><p>ファイルの一部または全部を仮想アドレス空間に対応付け、メモリを読むようにアクセスする仕組み。</p><p><strong>例</strong>　大きなアセットパックの索引をメモリマップする。</p><p><strong>関連</strong>　<a href="/study/os/memory-mapped-files.html">メモリマップドファイル</a> · <a href="/study/glossary/pc.html#virtual-memory">仮想メモリ</a> · <a href="/study/glossary/pc.html#page-fault">ページフォルト</a> · <a href="/study/glossary/pc.html#file-system">ファイルシステム</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/memory/file-mapping" target="_blank" rel="noreferrer">Microsoft — ファイルマッピング</a></p><h2 id="uefi" tabindex="-1">UEFI <a class="header-anchor" href="#uefi" aria-label="Permalink to &quot;UEFI {#uefi}&quot;">​</a></h2><p><strong>UEFI / Unified Extensible Firmware Interface</strong> ／ 読み ゆーいーえふあい</p><p>OSローダーとプラットフォームのファームウェアがやり取りするためのインターフェース仕様。UEFI 2.11では起動項目の選択やEFIアプリケーションの読み込みも定める。</p><p><strong>例</strong>　UEFIの起動順でWindows Boot Managerを先にする。</p><p><strong>関連</strong>　<a href="/study/glossary/pc.html#bios">BIOS</a> · <a href="/study/glossary/pc.html#firmware">ファームウェア</a> · <a href="/study/glossary/pc.html#boot-loader">ブートローダー</a></p><p><strong>出典</strong>　<a href="https://uefi.org/specs/UEFI/2.11/03_Boot_Manager.html" target="_blank" rel="noreferrer">UEFI Forum — UEFI 2.11、Boot Manager</a></p><h2 id="user-mode" tabindex="-1">ユーザーモード <a class="header-anchor" href="#user-mode" aria-label="Permalink to &quot;ユーザーモード {#user-mode}&quot;">​</a></h2><p><strong>user mode</strong> ／ 読み ゆーざーもーど</p><p>一般のアプリなどが動く実行状態。CPUの特権操作や他のプロセスのメモリへのアクセスが制限される。</p><p><strong>例</strong>　ゲームの更新処理はユーザーモードで実行する。</p><p><strong>関連</strong>　<a href="/study/os/operating-system-basics.html">OSの役割とユーザーモード・カーネル</a> · <a href="/study/glossary/pc.html#kernel-mode">カーネルモード</a> · <a href="/study/glossary/pc.html#process">プロセス</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/gettingstarted/user-mode-and-kernel-mode" target="_blank" rel="noreferrer">Microsoft — ユーザーモードとカーネルモード</a></p><h2 id="latency" tabindex="-1">レイテンシ <a class="header-anchor" href="#latency" aria-label="Permalink to &quot;レイテンシ {#latency}&quot;">​</a></h2><p><strong>latency</strong> ／ 読み れいてんし / れいてんしー / ちえん</p><p>要求を出してから、決めた応答や完了を観測するまでの時間。</p><p><strong>この分野での意味</strong>　ネットワークの片道、往復、ゲームの入力から画面表示など、測定の始点と終点で値が変わる。</p><p><strong>例</strong>　入力から表示までのレイテンシをミリ秒で測る。</p><p><strong>関連</strong>　<a href="/study/graphics/optimization/input-to-display-latency.html">入力から画面表示までの遅延</a> · <a href="/study/glossary/pc.html#throughput">スループット</a> · <a href="/study/glossary/pc.html#bandwidth">帯域</a></p><p><strong>出典</strong>　<a href="https://www.rfc-editor.org/info/rfc1242/" target="_blank" rel="noreferrer">IETF RFC 1242 — ネットワーク機器の計測用語</a> · <a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel64-and-ia32-architectures-optimization.html" target="_blank" rel="noreferrer">Intel — Intel 64・IA-32 Optimization Reference Manuals</a></p><h2 id="registry" tabindex="-1">レジストリ <a class="header-anchor" href="#registry" aria-label="Permalink to &quot;レジストリ {#registry}&quot;">​</a></h2><p><strong>Windows Registry / registry</strong> ／ 読み れじすとり</p><p>WindowsがOSやアプリなどの設定をキーと値で管理する階層型のデータベース。</p><p><strong>この分野での意味</strong>　パッケージの配布先を表すpackage registryや、CPUのレジスタとは別のもの。</p><p><strong>例</strong>　Windowsのレジストリからアプリの設定を読む。</p><p><strong>関連</strong>　<a href="/study/glossary/pc.html#environment-variable">環境変数</a> · <a href="/study/glossary/pc.html#service">サービス</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/sysinfo/registry" target="_blank" rel="noreferrer">Microsoft — レジストリ</a></p><h2 id="working-set" tabindex="-1">ワーキングセット <a class="header-anchor" href="#working-set" aria-label="Permalink to &quot;ワーキングセット {#working-set}&quot;">​</a></h2><p><strong>working set</strong> ／ 読み わーきんぐせっと</p><p>Windowsのメモリ計測では、プロセスの仮想アドレス空間のうち現在RAMに常駐しているページの集合。</p><p><strong>この分野での意味</strong>　性能の議論では、ある時間内に繰り返しアクセスするデータのまとまりを指すこともある。</p><p><strong>例</strong>　ロード後にプロセスのワーキングセットが増えた。</p><p><strong>関連</strong>　<a href="/study/os/virtual-memory.html">仮想メモリとアドレス変換</a> · <a href="/study/glossary/pc.html#page">ページ</a> · <a href="/study/glossary/pc.html#swap">スワップ</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/memory/working-set" target="_blank" rel="noreferrer">Microsoft — ワーキングセット</a> · <a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel64-and-ia32-architectures-optimization.html" target="_blank" rel="noreferrer">Intel — Intel 64・IA-32 Optimization Reference Manuals</a></p><h2 id="interrupt" tabindex="-1">割り込み <a class="header-anchor" href="#interrupt" aria-label="Permalink to &quot;割り込み {#interrupt}&quot;">​</a></h2><p><strong>interrupt</strong> ／ 読み わりこみ</p><p>機器などの通知を受けて、CPUが現在の処理の途中で所定のハンドラーへ実行を移す仕組み。</p><p><strong>例</strong>　NICが受信を通知し、ドライバーの割り込み処理が走る。</p><p><strong>関連</strong>　<a href="/study/hardware/io/nic-receive-queues.html">NICの受信キュー</a> · <a href="/study/glossary/pc.html#driver">ドライバー</a> · <a href="/study/glossary/pc.html#dma">DMA</a> · <a href="/study/glossary/pc.html#polling">ポーリング</a> · <a href="/study/glossary/pc.html#irq">IRQ</a></p><p><strong>出典</strong>　<a href="https://docs.kernel.org/core-api/genericirq.html" target="_blank" rel="noreferrer">Linuxカーネル文書 — 割り込みの処理</a> · <a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html" target="_blank" rel="noreferrer">Intel — Intel 64・IA-32 Software Developer Manuals</a></p>',365)])])}const m=e(o,[["render",n]]);export{d as __pageData,m as default};
